require('dotenv').config()
const { GoogleGenAI } = require('@google/genai')

async function testGemini() {
  try {
    console.log('API Key:', process.env.GEMINI_API_KEY ? 'FOUND (starts with ' + process.env.GEMINI_API_KEY.substring(0, 5) + '...)' : 'NOT FOUND')
    if (!process.env.GEMINI_API_KEY) {
      throw new Error('GEMINI_API_KEY env var is missing')
    }
    const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY })
    console.log('Calling gemini-2.5-flash with test prompt...')
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: 'Hello, respond with a single word "OK" if you are working.'
    })
    console.log('Response status:', response.text ? 'SUCCESS' : 'EMPTY')
    console.log('Response text:', response.text.trim())
  } catch (err) {
    console.error('❌ Gemini Error:', err)
  }
}

testGemini()
